-- Item 851: MCQ — Lecture d'oscilloscope, courbe de charge RC (difficulty 3)
INSERT INTO items (id, skill_id, item_type, difficulty_level, content_language, question, explanation, tags) VALUES
(
  '44444444-0000-0000-0000-000000000851',
  '33333333-0000-0000-0000-000000000029',
  'mcq', 3, 'fr',
  '{"stem": "On réalise la charge d''un condensateur dans un circuit RC série. L''oscilloscope affiche la courbe $u_C(t)$ ci-dessous. La sensibilité horizontale est $5\\,\\text{ms/div}$ et la sensibilité verticale est $2\\,\\text{V/div}$. Déterminer la constante de temps $\\tau$ du circuit.", "latex": true, "figure": {"svg": "<svg viewBox=\"0 0 400 250\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"40\" y=\"10\" width=\"350\" height=\"220\" fill=\"#1a1a2e\" rx=\"4\"/><line x1=\"40\" y1=\"230\" x2=\"390\" y2=\"230\" stroke=\"#64748B\" stroke-width=\"0.5\"/><line x1=\"40\" y1=\"10\" x2=\"40\" y2=\"230\" stroke=\"#64748B\" stroke-width=\"0.5\"/><g stroke=\"#334155\" stroke-width=\"0.3\"><line x1=\"110\" y1=\"10\" x2=\"110\" y2=\"230\"/><line x1=\"180\" y1=\"10\" x2=\"180\" y2=\"230\"/><line x1=\"250\" y1=\"10\" x2=\"250\" y2=\"230\"/><line x1=\"320\" y1=\"10\" x2=\"320\" y2=\"230\"/><line x1=\"390\" y1=\"10\" x2=\"390\" y2=\"230\"/><line x1=\"40\" y1=\"186\" x2=\"390\" y2=\"186\"/><line x1=\"40\" y1=\"142\" x2=\"390\" y2=\"142\"/><line x1=\"40\" y1=\"98\" x2=\"390\" y2=\"98\"/><line x1=\"40\" y1=\"54\" x2=\"390\" y2=\"54\"/></g><text x=\"20\" y=\"234\" fill=\"#64748B\" font-size=\"9\">0</text><text x=\"105\" y=\"245\" fill=\"#64748B\" font-size=\"9\">1</text><text x=\"175\" y=\"245\" fill=\"#64748B\" font-size=\"9\">2</text><text x=\"245\" y=\"245\" fill=\"#64748B\" font-size=\"9\">3</text><text x=\"315\" y=\"245\" fill=\"#64748B\" font-size=\"9\">4</text><text x=\"385\" y=\"245\" fill=\"#64748B\" font-size=\"9\">5</text><text x=\"25\" y=\"190\" fill=\"#64748B\" font-size=\"9\">2</text><text x=\"25\" y=\"146\" fill=\"#64748B\" font-size=\"9\">4</text><text x=\"25\" y=\"102\" fill=\"#64748B\" font-size=\"9\">6</text><text x=\"25\" y=\"58\" fill=\"#64748B\" font-size=\"9\">8</text><text x=\"15\" y=\"18\" fill=\"#64748B\" font-size=\"9\">10</text><path d=\"M40,230 C70,170 100,120 140,85 C180,58 240,40 320,32 L390,30\" fill=\"none\" stroke=\"#4A90D9\" stroke-width=\"2\"/><line x1=\"40\" y1=\"30\" x2=\"390\" y2=\"30\" stroke=\"#E8744F\" stroke-width=\"1\" stroke-dasharray=\"5,3\"/><text x=\"392\" y=\"34\" fill=\"#E8744F\" font-size=\"9\">E</text><line x1=\"110\" y1=\"230\" x2=\"110\" y2=\"100\" stroke=\"#10B981\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><line x1=\"40\" y1=\"100\" x2=\"110\" y2=\"100\" stroke=\"#10B981\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><text x=\"95\" y=\"248\" fill=\"#10B981\" font-size=\"10\" font-weight=\"bold\">τ</text><text x=\"200\" y=\"248\" fill=\"#64748B\" font-size=\"9\">div</text></svg>", "alt_text": "Courbe de charge u_C(t) sur oscilloscope, E = 10 V, τ correspond à 1 div horizontale"}, "choices": ["$\\tau = 5\\,\\text{ms}$", "$\\tau = 10\\,\\text{ms}$", "$\\tau = 15\\,\\text{ms}$", "$\\tau = 2,5\\,\\text{ms}$"], "correct_index": 0}',
  '{"text_fr": "Sur la courbe de charge, la constante de temps $\\tau$ correspond au point où $u_C = 0{,}63 \\times E$. Ici $E = 10\\,\\text{V}$, donc $u_C(\\tau) = 6{,}3\\,\\text{V}$. Sur la courbe, ce point est atteint à $1\\,\\text{div}$ horizontale. Avec la sensibilité de $5\\,\\text{ms/div}$, on obtient $\\tau = 1 \\times 5 = 5\\,\\text{ms}$.", "steps": ["Identifier la tension finale $E = 5\\,\\text{div} \\times 2\\,\\text{V/div} = 10\\,\\text{V}$", "Calculer $u_C(\\tau) = 0{,}63 \\times E = 0{,}63 \\times 10 = 6{,}3\\,\\text{V}$", "Repérer sur la courbe : $u_C = 6{,}3\\,\\text{V}$ correspond à $1\\,\\text{div}$ horizontale", "$\\tau = 1 \\times 5\\,\\text{ms/div} = 5\\,\\text{ms}$"]}',
  '{"oscilloscope","constante_de_temps","charge","bac_2024"}'
);

-- Item 852: Numeric — Déterminer R à partir de τ et C (difficulty 3)
INSERT INTO items (id, skill_id, item_type, difficulty_level, content_language, question, explanation, tags) VALUES
(
  '44444444-0000-0000-0000-000000000852',
  '33333333-0000-0000-0000-000000000029',
  'numeric', 3, 'fr',
  '{"stem": "On considère le circuit RC série ci-dessous. Le condensateur, initialement déchargé, est soumis à un échelon de tension $E = 12\\,\\text{V}$ à la fermeture de l''interrupteur K. La capacité du condensateur est $C = 22\\,\\mu\\text{F}$ et on mesure expérimentalement $\\tau = 11\\,\\text{ms}$. Calculer la résistance $R$ (en $\\Omega$).", "latex": true, "correct_value": 500, "tolerance": 5, "figure": {"svg": "<svg viewBox=\"0 0 400 200\" xmlns=\"http://www.w3.org/2000/svg\"><line x1=\"50\" y1=\"40\" x2=\"120\" y2=\"40\" stroke=\"#4A90D9\" stroke-width=\"2\"/><circle cx=\"130\" cy=\"40\" r=\"3\" fill=\"#E8744F\"/><line x1=\"133\" y1=\"40\" x2=\"140\" y2=\"40\" stroke=\"#4A90D9\" stroke-width=\"2\"/><line x1=\"140\" y1=\"35\" x2=\"160\" y2=\"35\" stroke=\"#E8744F\" stroke-width=\"2\"/><line x1=\"160\" y1=\"35\" x2=\"160\" y2=\"45\" stroke=\"#E8744F\" stroke-width=\"2\"/><line x1=\"140\" y1=\"45\" x2=\"160\" y2=\"45\" stroke=\"#E8744F\" stroke-width=\"1.5\" stroke-dasharray=\"2,2\"/><text x=\"143\" y=\"58\" fill=\"#E8744F\" font-size=\"11\" font-weight=\"bold\">K</text><line x1=\"160\" y1=\"40\" x2=\"200\" y2=\"40\" stroke=\"#4A90D9\" stroke-width=\"2\"/><rect x=\"200\" y=\"30\" width=\"60\" height=\"20\" fill=\"none\" stroke=\"#4A90D9\" stroke-width=\"2\" rx=\"2\"/><text x=\"222\" y=\"45\" fill=\"#4A90D9\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"bold\">R</text><line x1=\"260\" y1=\"40\" x2=\"330\" y2=\"40\" stroke=\"#4A90D9\" stroke-width=\"2\"/><line x1=\"330\" y1=\"40\" x2=\"330\" y2=\"60\" stroke=\"#4A90D9\" stroke-width=\"2\"/><line x1=\"320\" y1=\"60\" x2=\"340\" y2=\"60\" stroke=\"#4A90D9\" stroke-width=\"2\"/><line x1=\"323\" y1=\"70\" x2=\"337\" y2=\"70\" stroke=\"#4A90D9\" stroke-width=\"2\"/><line x1=\"330\" y1=\"70\" x2=\"330\" y2=\"160\" stroke=\"#4A90D9\" stroke-width=\"2\"/><text x=\"345\" y=\"68\" fill=\"#4A90D9\" font-size=\"12\" font-weight=\"bold\">C</text><line x1=\"330\" y1=\"160\" x2=\"50\" y2=\"160\" stroke=\"#4A90D9\" stroke-width=\"2\"/><line x1=\"50\" y1=\"160\" x2=\"50\" y2=\"40\" stroke=\"#4A90D9\" stroke-width=\"2\"/><circle cx=\"50\" cy=\"90\" r=\"15\" fill=\"none\" stroke=\"#10B981\" stroke-width=\"2\"/><text x=\"50\" y=\"95\" fill=\"#10B981\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"bold\">E</text><line x1=\"44\" y1=\"78\" x2=\"44\" y2=\"72\" stroke=\"#10B981\" stroke-width=\"1.5\"/><line x1=\"41\" y1=\"75\" x2=\"47\" y2=\"75\" stroke=\"#10B981\" stroke-width=\"1.5\"/><line x1=\"41\" y1=\"105\" x2=\"47\" y2=\"105\" stroke=\"#10B981\" stroke-width=\"1.5\"/></svg>", "alt_text": "Circuit RC série avec générateur E, interrupteur K, résistance R et condensateur C"}}',
  '{"text_fr": "La constante de temps d''un circuit RC est $\\tau = R \\times C$. On en déduit $R = \\tau / C$. Application numérique : $R = 11 \\times 10^{-3} / (22 \\times 10^{-6}) = 500\\,\\Omega$.", "steps": ["Formule : $\\tau = R \\times C$", "On isole : $R = \\tau / C$", "$R = \\dfrac{11 \\times 10^{-3}}{22 \\times 10^{-6}}$", "$R = 0{,}5 \\times 10^{3} = 500\\,\\Omega$"], "figure": {"svg": "<svg viewBox=\"0 0 400 120\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"20\" y=\"30\" fill=\"#4A90D9\" font-size=\"14\">Données : τ = 11 ms, C = 22 μF</text><text x=\"20\" y=\"55\" fill=\"#64748B\" font-size=\"14\">R = τ / C = 11×10⁻³ / 22×10⁻⁶</text><text x=\"20\" y=\"80\" fill=\"#10B981\" font-size=\"14\" font-weight=\"bold\">R = 500 Ω</text></svg>", "alt_text": "Calcul de R à partir de τ et C"}}',
  '{"constante_de_temps","resistance","circuit_RC","bac_2023"}'
);

-- Item 853: Numeric — Décharge RC, temps pour atteindre un seuil (difficulty 4)
INSERT INTO items (id, skill_id, item_type, difficulty_level, content_language, question, explanation, tags) VALUES
(
  '44444444-0000-0000-0000-000000000853',
  '33333333-0000-0000-0000-000000000029',
  'numeric', 4, 'fr',
  '{"stem": "Un condensateur de capacité $C = 47\\,\\mu\\text{F}$, chargé sous $U_0 = 9\\,\\text{V}$, se décharge à travers une résistance $R = 10\\,\\text{k}\\Omega$. On observe la courbe de décharge ci-dessous. Déterminer l''instant $t_1$ (en ms) pour lequel $u_C = 1\\,\\text{V}$.", "latex": true, "correct_value": 1032, "tolerance": 15, "figure": {"svg": "<svg viewBox=\"0 0 400 250\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"50\" y=\"10\" width=\"340\" height=\"220\" fill=\"#fafafa\" stroke=\"#64748B\" stroke-width=\"1\" rx=\"2\"/><line x1=\"50\" y1=\"230\" x2=\"390\" y2=\"230\" stroke=\"#64748B\" stroke-width=\"1\"/><line x1=\"50\" y1=\"10\" x2=\"50\" y2=\"230\" stroke=\"#64748B\" stroke-width=\"1\"/><text x=\"45\" y=\"248\" fill=\"#64748B\" font-size=\"9\">0</text><text x=\"30\" y=\"28\" fill=\"#64748B\" font-size=\"9\">U₀</text><text x=\"395\" y=\"234\" fill=\"#64748B\" font-size=\"10\">t</text><text x=\"38\" y=\"8\" fill=\"#64748B\" font-size=\"10\">u_C</text><path d=\"M50,30 C100,50 150,90 200,140 C250,180 300,210 390,225\" fill=\"none\" stroke=\"#E8744F\" stroke-width=\"2.5\"/><line x1=\"50\" y1=\"206\" x2=\"390\" y2=\"206\" stroke=\"#10B981\" stroke-width=\"1\" stroke-dasharray=\"4,3\"/><text x=\"392\" y=\"210\" fill=\"#10B981\" font-size=\"9\">1 V</text><line x1=\"310\" y1=\"206\" x2=\"310\" y2=\"230\" stroke=\"#10B981\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><text x=\"303\" y=\"245\" fill=\"#10B981\" font-size=\"9\">t₁</text><circle cx=\"310\" cy=\"206\" r=\"3\" fill=\"#10B981\"/><text x=\"120\" y=\"248\" fill=\"#64748B\" font-size=\"9\">τ</text><text x=\"190\" y=\"248\" fill=\"#64748B\" font-size=\"9\">2τ</text><text x=\"260\" y=\"248\" fill=\"#64748B\" font-size=\"9\">3τ</text></svg>", "alt_text": "Courbe de décharge exponentielle du condensateur, de U₀ = 9 V vers 0, avec le seuil 1 V marqué"}}',
  '{"text_fr": "Lors de la décharge : $u_C(t) = U_0 \\cdot e^{-t/\\tau}$. On cherche $t_1$ tel que $u_C(t_1) = 1\\,\\text{V}$. On calcule d''abord $\\tau = RC = 10 \\times 10^3 \\times 47 \\times 10^{-6} = 0{,}47\\,\\text{s} = 470\\,\\text{ms}$. Puis $1 = 9 \\cdot e^{-t_1/470}$, soit $e^{-t_1/470} = 1/9$, d''où $-t_1/470 = \\ln(1/9) = -\\ln 9$. Finalement $t_1 = 470 \\times \\ln 9 = 470 \\times 2{,}197 \\approx 1032\\,\\text{ms}$.", "steps": ["$\\tau = RC = 10 \\times 10^3 \\times 47 \\times 10^{-6} = 470\\,\\text{ms}$", "$u_C(t_1) = U_0 \\cdot e^{-t_1/\\tau} = 1\\,\\text{V}$", "$e^{-t_1/\\tau} = 1/U_0 = 1/9$", "$t_1 = \\tau \\cdot \\ln(U_0) = 470 \\times \\ln 9 \\approx 1032\\,\\text{ms}$"]}',
  '{"decharge","logarithme","seuil","bac_2024"}'
);

-- Item 854: True/False — Énergie dans un condensateur (difficulty 2)
INSERT INTO items (id, skill_id, item_type, difficulty_level, content_language, question, explanation, tags) VALUES
(
  '44444444-0000-0000-0000-000000000854',
  '33333333-0000-0000-0000-000000000029',
  'true_false', 2, 'fr',
  '{"stem": "On considère le circuit RC ci-dessous. L''énergie stockée dans un condensateur de capacité $C$ chargé sous une tension $u_C$ est donnée par $E_C = C \\cdot u_C^2$.", "latex": true, "correct_answer": false, "figure": {"svg": "<svg viewBox=\"0 0 400 180\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"140\" y=\"20\" width=\"120\" height=\"140\" fill=\"none\" stroke=\"#4A90D9\" stroke-width=\"2\" rx=\"6\"/><text x=\"200\" y=\"95\" fill=\"#4A90D9\" font-size=\"14\" text-anchor=\"middle\" font-weight=\"bold\">C</text><line x1=\"190\" y1=\"50\" x2=\"210\" y2=\"50\" stroke=\"#4A90D9\" stroke-width=\"3\"/><line x1=\"190\" y1=\"60\" x2=\"210\" y2=\"60\" stroke=\"#4A90D9\" stroke-width=\"3\"/><text x=\"220\" y=\"58\" fill=\"#E8744F\" font-size=\"12\">+</text><text x=\"175\" y=\"58\" fill=\"#4A90D9\" font-size=\"12\">−</text><text x=\"200\" y=\"130\" fill=\"#64748B\" font-size=\"13\" text-anchor=\"middle\">u_C</text><line x1=\"200\" y1=\"110\" x2=\"200\" y2=\"120\" stroke=\"#64748B\" stroke-width=\"1\"/><path d=\"M190,115 L200,120 L210,115\" fill=\"none\" stroke=\"#64748B\" stroke-width=\"1\"/><text x=\"70\" y=\"95\" fill=\"#64748B\" font-size=\"13\">E_C = ?</text></svg>", "alt_text": "Schéma symbolique d''un condensateur avec tension u_C et question sur l''énergie stockée"}}',
  '{"text_fr": "Faux. L''expression correcte de l''énergie stockée dans un condensateur est $E_C = \\frac{1}{2} C u_C^2$. Le facteur $\\frac{1}{2}$ est indispensable. C''est une erreur classique au Bac de l''oublier.", "steps": ["L''énergie stockée dans un condensateur est $E_C = \\frac{1}{2} C u_C^2$", "L''expression $E_C = C u_C^2$ est incorrecte car il manque le facteur $\\frac{1}{2}$", "Attention : c''est un piège fréquent au Bac !"]}',
  '{"energie","condensateur","piege_classique","bac_style"}'
);

-- Item 855: MCQ — Établissement du courant RL, lecture graphique (difficulty 3)
INSERT INTO items (id, skill_id, item_type, difficulty_level, content_language, question, explanation, tags) VALUES
(
  '44444444-0000-0000-0000-000000000855',
  '33333333-0000-0000-0000-000000000029',
  'mcq', 3, 'fr',
  '{"stem": "On ferme l''interrupteur K dans le circuit RL série ci-dessous ($E = 6\\,\\text{V}$, $R = 100\\,\\Omega$, $L = 0{,}2\\,\\text{H}$). L''oscilloscope affiche la courbe $i(t)$. Quelle est la valeur de l''intensité en régime permanent $I_0$ ?", "latex": true, "figure": {"svg": "<svg viewBox=\"0 0 400 250\" xmlns=\"http://www.w3.org/2000/svg\"><g><line x1=\"30\" y1=\"30\" x2=\"100\" y2=\"30\" stroke=\"#4A90D9\" stroke-width=\"2\"/><circle cx=\"110\" cy=\"30\" r=\"3\" fill=\"#E8744F\"/><line x1=\"113\" y1=\"30\" x2=\"130\" y2=\"30\" stroke=\"#4A90D9\" stroke-width=\"2\"/><line x1=\"130\" y1=\"25\" x2=\"150\" y2=\"25\" stroke=\"#E8744F\" stroke-width=\"2\"/><line x1=\"150\" y1=\"25\" x2=\"150\" y2=\"35\" stroke=\"#E8744F\" stroke-width=\"2\"/><text x=\"133\" y=\"48\" fill=\"#E8744F\" font-size=\"10\" font-weight=\"bold\">K</text><line x1=\"150\" y1=\"30\" x2=\"190\" y2=\"30\" stroke=\"#4A90D9\" stroke-width=\"2\"/><rect x=\"190\" y=\"20\" width=\"50\" height=\"20\" fill=\"none\" stroke=\"#4A90D9\" stroke-width=\"2\" rx=\"2\"/><text x=\"210\" y=\"35\" fill=\"#4A90D9\" font-size=\"11\" text-anchor=\"middle\">R</text><line x1=\"240\" y1=\"30\" x2=\"280\" y2=\"30\" stroke=\"#4A90D9\" stroke-width=\"2\"/><path d=\"M280,25 C287,20 293,40 300,25 C307,10 313,40 320,25\" fill=\"none\" stroke=\"#4A90D9\" stroke-width=\"2\"/><text x=\"300\" y=\"48\" fill=\"#4A90D9\" font-size=\"11\" text-anchor=\"middle\">L</text><line x1=\"320\" y1=\"30\" x2=\"370\" y2=\"30\" stroke=\"#4A90D9\" stroke-width=\"2\"/><line x1=\"370\" y1=\"30\" x2=\"370\" y2=\"170\" stroke=\"#4A90D9\" stroke-width=\"2\"/><line x1=\"370\" y1=\"170\" x2=\"30\" y2=\"170\" stroke=\"#4A90D9\" stroke-width=\"2\"/><line x1=\"30\" y1=\"170\" x2=\"30\" y2=\"30\" stroke=\"#4A90D9\" stroke-width=\"2\"/><circle cx=\"30\" cy=\"100\" r=\"15\" fill=\"none\" stroke=\"#10B981\" stroke-width=\"2\"/><text x=\"30\" y=\"105\" fill=\"#10B981\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"bold\">E</text></g><g transform=\"translate(0,0)\"><rect x=\"50\" y=\"185\" width=\"300\" height=\"55\" fill=\"#1a1a2e\" rx=\"3\"/><line x1=\"50\" y1=\"235\" x2=\"350\" y2=\"235\" stroke=\"#334155\" stroke-width=\"0.5\"/><line x1=\"50\" y1=\"185\" x2=\"50\" y2=\"240\" stroke=\"#334155\" stroke-width=\"0.5\"/><path d=\"M50,235 C80,220 110,205 150,198 C200,192 260,190 350,190\" fill=\"none\" stroke=\"#4A90D9\" stroke-width=\"2\"/><line x1=\"50\" y1=\"190\" x2=\"350\" y2=\"190\" stroke=\"#E8744F\" stroke-width=\"1\" stroke-dasharray=\"4,3\"/><text x=\"355\" y=\"194\" fill=\"#E8744F\" font-size=\"9\">I₀</text><text x=\"355\" y=\"238\" fill=\"#64748B\" font-size=\"9\">t</text><text x=\"38\" y=\"240\" fill=\"#64748B\" font-size=\"9\">0</text></g></svg>", "alt_text": "Circuit RL série avec E, K, R, L et courbe i(t) montrant l''établissement du courant"}, "choices": ["$I_0 = 60\\,\\text{mA}$", "$I_0 = 6\\,\\text{mA}$", "$I_0 = 0{,}6\\,\\text{A}$", "$I_0 = 30\\,\\text{mA}$"], "correct_index": 0}',
  '{"text_fr": "En régime permanent, la bobine se comporte comme un fil (son inductance n''intervient plus car $di/dt = 0$). Donc $u_L = 0$ et toute la tension est aux bornes de $R$ : $I_0 = E/R = 6/100 = 0{,}06\\,\\text{A} = 60\\,\\text{mA}$.", "steps": ["En régime permanent : $di/dt = 0$, donc $u_L = L \\cdot di/dt = 0$", "Loi des mailles : $E = u_R + u_L = R \\cdot I_0 + 0$", "$I_0 = E/R = 6/100 = 0{,}06\\,\\text{A}$", "$I_0 = 60\\,\\text{mA}$"]}',
  '{"etablissement_courant","regime_permanent","circuit_RL","bac_2023"}'
);

-- Item 856: Numeric — Constante de temps RL, détermination de L (difficulty 4)
INSERT INTO items (id, skill_id, item_type, difficulty_level, content_language, question, explanation, tags) VALUES
(
  '44444444-0000-0000-0000-000000000856',
  '33333333-0000-0000-0000-000000000029',
  'numeric', 4, 'fr',
  '{"stem": "Un circuit RL série est alimenté par un générateur de f.é.m. $E = 12\\,\\text{V}$ et de résistance interne négligeable. La résistance du circuit est $R = 40\\,\\Omega$. On mesure graphiquement sur la courbe $i(t)$ que la tangente à l''origine coupe l''asymptote $I_0$ à l''instant $t = 5\\,\\text{ms}$. En déduire l''inductance $L$ (en mH) de la bobine.", "latex": true, "correct_value": 200, "tolerance": 3, "figure": {"svg": "<svg viewBox=\"0 0 400 250\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"40\" y=\"10\" width=\"350\" height=\"220\" fill=\"#fafafa\" stroke=\"#64748B\" stroke-width=\"1\" rx=\"2\"/><line x1=\"40\" y1=\"230\" x2=\"390\" y2=\"230\" stroke=\"#64748B\" stroke-width=\"1\"/><line x1=\"40\" y1=\"10\" x2=\"40\" y2=\"230\" stroke=\"#64748B\" stroke-width=\"1\"/><text x=\"20\" y=\"234\" fill=\"#64748B\" font-size=\"9\">0</text><text x=\"395\" y=\"234\" fill=\"#64748B\" font-size=\"10\">t (ms)</text><text x=\"25\" y=\"15\" fill=\"#64748B\" font-size=\"10\">i (A)</text><line x1=\"40\" y1=\"50\" x2=\"390\" y2=\"50\" stroke=\"#E8744F\" stroke-width=\"1\" stroke-dasharray=\"5,3\"/><text x=\"392\" y=\"54\" fill=\"#E8744F\" font-size=\"10\">I₀ = 0,3 A</text><path d=\"M40,230 C65,195 95,160 140,125 C190,95 250,68 320,56 L390,52\" fill=\"none\" stroke=\"#4A90D9\" stroke-width=\"2.5\"/><line x1=\"40\" y1=\"230\" x2=\"180\" y2=\"50\" stroke=\"#10B981\" stroke-width=\"1.5\" stroke-dasharray=\"6,3\"/><line x1=\"180\" y1=\"50\" x2=\"180\" y2=\"230\" stroke=\"#10B981\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><text x=\"175\" y=\"245\" fill=\"#10B981\" font-size=\"10\" font-weight=\"bold\">τ</text><text x=\"100\" y=\"248\" fill=\"#64748B\" font-size=\"9\">5</text><text x=\"170\" y=\"248\" fill=\"#64748B\" font-size=\"9\">10</text><text x=\"240\" y=\"248\" fill=\"#64748B\" font-size=\"9\">15</text><text x=\"310\" y=\"248\" fill=\"#64748B\" font-size=\"9\">20</text><circle cx=\"180\" cy=\"50\" r=\"4\" fill=\"#10B981\"/></svg>", "alt_text": "Courbe i(t) d''un circuit RL, tangente à l''origine coupant l''asymptote I₀ à t = τ = 5 ms"}}',
  '{"text_fr": "La tangente à l''origine de la courbe $i(t)$ coupe l''asymptote $I_0 = E/R$ à l''instant $t = \\tau$. Donc $\\tau = 5\\,\\text{ms}$. Or $\\tau = L/R$, d''où $L = \\tau \\times R = 5 \\times 10^{-3} \\times 40 = 0{,}2\\,\\text{H} = 200\\,\\text{mH}$.", "steps": ["La tangente à l''origine coupe l''asymptote à $t = \\tau$", "Donc $\\tau = 5\\,\\text{ms} = 5 \\times 10^{-3}\\,\\text{s}$", "$\\tau = L/R \\Rightarrow L = \\tau \\times R$", "$L = 5 \\times 10^{-3} \\times 40 = 0{,}2\\,\\text{H} = 200\\,\\text{mH}$"], "figure": {"svg": "<svg viewBox=\"0 0 400 80\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"20\" y=\"25\" fill=\"#4A90D9\" font-size=\"13\">τ = L/R  ⟹  L = τ × R</text><text x=\"20\" y=\"50\" fill=\"#64748B\" font-size=\"13\">L = 5×10⁻³ × 40 = 0,2 H</text><text x=\"20\" y=\"72\" fill=\"#10B981\" font-size=\"14\" font-weight=\"bold\">L = 200 mH</text></svg>", "alt_text": "Calcul : L = τ × R = 200 mH"}}',
  '{"tangente_origine","constante_de_temps","inductance","bac_2024"}'
);

-- Item 857: True/False — Équation différentielle charge RC (difficulty 3)
INSERT INTO items (id, skill_id, item_type, difficulty_level, content_language, question, explanation, tags) VALUES
(
  '44444444-0000-0000-0000-000000000857',
  '33333333-0000-0000-0000-000000000029',
  'true_false', 3, 'fr',
  '{"stem": "On considère le circuit RC série ci-dessous en régime de charge. L''équation différentielle vérifiée par $u_C$ est : $RC\\,\\dfrac{du_C}{dt} + u_C = E$.", "latex": true, "correct_answer": true, "figure": {"svg": "<svg viewBox=\"0 0 400 180\" xmlns=\"http://www.w3.org/2000/svg\"><line x1=\"30\" y1=\"30\" x2=\"80\" y2=\"30\" stroke=\"#4A90D9\" stroke-width=\"2\"/><circle cx=\"30\" cy=\"90\" r=\"15\" fill=\"none\" stroke=\"#10B981\" stroke-width=\"2\"/><text x=\"30\" y=\"95\" fill=\"#10B981\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"bold\">E</text><line x1=\"30\" y1=\"105\" x2=\"30\" y2=\"150\" stroke=\"#4A90D9\" stroke-width=\"2\"/><line x1=\"30\" y1=\"30\" x2=\"30\" y2=\"75\" stroke=\"#4A90D9\" stroke-width=\"2\"/><rect x=\"80\" y=\"20\" width=\"60\" height=\"20\" fill=\"none\" stroke=\"#4A90D9\" stroke-width=\"2\" rx=\"2\"/><text x=\"110\" y=\"35\" fill=\"#4A90D9\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"bold\">R</text><line x1=\"140\" y1=\"30\" x2=\"200\" y2=\"30\" stroke=\"#4A90D9\" stroke-width=\"2\"/><text x=\"170\" y=\"22\" fill=\"#64748B\" font-size=\"10\">i →</text><line x1=\"200\" y1=\"30\" x2=\"200\" y2=\"60\" stroke=\"#4A90D9\" stroke-width=\"2\"/><line x1=\"185\" y1=\"60\" x2=\"215\" y2=\"60\" stroke=\"#4A90D9\" stroke-width=\"2.5\"/><line x1=\"190\" y1=\"70\" x2=\"210\" y2=\"70\" stroke=\"#4A90D9\" stroke-width=\"2.5\"/><text x=\"220\" y=\"68\" fill=\"#4A90D9\" font-size=\"12\" font-weight=\"bold\">C</text><line x1=\"200\" y1=\"70\" x2=\"200\" y2=\"150\" stroke=\"#4A90D9\" stroke-width=\"2\"/><line x1=\"200\" y1=\"150\" x2=\"30\" y2=\"150\" stroke=\"#4A90D9\" stroke-width=\"2\"/><path d=\"M210,85 L210,115\" stroke=\"#E8744F\" stroke-width=\"1.5\"/><path d=\"M213,110 L210,118 L207,110\" fill=\"#E8744F\"/><text x=\"218\" y=\"105\" fill=\"#E8744F\" font-size=\"11\">u_C</text><path d=\"M95,48 L135,48\" stroke=\"#E8744F\" stroke-width=\"1.5\"/><path d=\"M130,45 L138,48 L130,51\" fill=\"#E8744F\"/><text x=\"110\" y=\"60\" fill=\"#E8744F\" font-size=\"11\" text-anchor=\"middle\">u_R</text></svg>", "alt_text": "Circuit RC série avec fléchage des tensions u_R et u_C et sens du courant i"}}',
  '{"text_fr": "Vrai. En appliquant la loi des mailles : $E = u_R + u_C = Ri + u_C$. Or $i = C\\,du_C/dt$, donc $E = RC\\,du_C/dt + u_C$, ce qui donne bien $RC\\,du_C/dt + u_C = E$. C''est l''équation différentielle du premier ordre à coefficients constants qui régit la charge du condensateur.", "steps": ["Loi des mailles : $E = u_R + u_C$", "$u_R = Ri$ et $i = C\\,\\dfrac{du_C}{dt}$", "Donc $E = RC\\,\\dfrac{du_C}{dt} + u_C$", "C''est une équation différentielle du 1er ordre à coefficients constants"]}',
  '{"equation_differentielle","charge","loi_des_mailles","bac_2023"}'
);

-- Item 858: MCQ — Énergie dans une bobine, interprétation graphique (difficulty 5)
INSERT INTO items (id, skill_id, item_type, difficulty_level, content_language, question, explanation, tags) VALUES
(
  '44444444-0000-0000-0000-000000000858',
  '33333333-0000-0000-0000-000000000029',
  'mcq', 5, 'fr',
  '{"stem": "Dans un circuit RL série ($E = 10\\,\\text{V}$, $R = 50\\,\\Omega$, $L = 0{,}5\\,\\text{H}$), on trace la courbe de l''énergie $E_L(t) = \\frac{1}{2}Li^2$ stockée dans la bobine pendant l''établissement du courant. Quelle est la valeur maximale $E_{L,\\text{max}}$ de cette énergie (en mJ) ?", "latex": true, "figure": {"svg": "<svg viewBox=\"0 0 400 250\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"40\" y=\"10\" width=\"350\" height=\"220\" fill=\"#fafafa\" stroke=\"#64748B\" stroke-width=\"1\" rx=\"2\"/><line x1=\"40\" y1=\"230\" x2=\"390\" y2=\"230\" stroke=\"#64748B\" stroke-width=\"1\"/><line x1=\"40\" y1=\"10\" x2=\"40\" y2=\"230\" stroke=\"#64748B\" stroke-width=\"1\"/><text x=\"20\" y=\"234\" fill=\"#64748B\" font-size=\"9\">0</text><text x=\"390\" y=\"248\" fill=\"#64748B\" font-size=\"10\">t</text><text x=\"10\" y=\"15\" fill=\"#64748B\" font-size=\"10\">E_L (mJ)</text><path d=\"M40,230 C70,210 110,170 160,115 C210,72 280,42 350,32 L390,30\" fill=\"none\" stroke=\"#E8744F\" stroke-width=\"2.5\"/><line x1=\"40\" y1=\"30\" x2=\"390\" y2=\"30\" stroke=\"#10B981\" stroke-width=\"1\" stroke-dasharray=\"5,3\"/><text x=\"392\" y=\"34\" fill=\"#10B981\" font-size=\"10\">E_L max</text><text x=\"120\" y=\"248\" fill=\"#64748B\" font-size=\"9\">τ</text><text x=\"200\" y=\"248\" fill=\"#64748B\" font-size=\"9\">2τ</text><text x=\"280\" y=\"248\" fill=\"#64748B\" font-size=\"9\">3τ</text><text x=\"360\" y=\"248\" fill=\"#64748B\" font-size=\"9\">4τ</text></svg>", "alt_text": "Courbe de l''énergie E_L(t) stockée dans la bobine, croissante vers E_L max"}, "choices": ["$E_{L,\\text{max}} = 10\\,\\text{mJ}$", "$E_{L,\\text{max}} = 20\\,\\text{mJ}$", "$E_{L,\\text{max}} = 50\\,\\text{mJ}$", "$E_{L,\\text{max}} = 100\\,\\text{mJ}$"], "correct_index": 0}',
  '{"text_fr": "En régime permanent, $I_0 = E/R = 10/50 = 0{,}2\\,\\text{A}$. L''énergie maximale stockée dans la bobine est $E_{L,\\text{max}} = \\frac{1}{2}LI_0^2 = \\frac{1}{2} \\times 0{,}5 \\times (0{,}2)^2 = \\frac{1}{2} \\times 0{,}5 \\times 0{,}04 = 0{,}01\\,\\text{J} = 10\\,\\text{mJ}$. Attention : la bonne réponse est $10\\,\\text{mJ}$, pas $20\\,\\text{mJ}$. Vérifions : $E_{L,\\text{max}} = \\frac{1}{2} \\times 0{,}5 \\times 0{,}04 = 0{,}01\\,\\text{J} = 10\\,\\text{mJ}$.", "steps": ["$I_0 = E/R = 10/50 = 0{,}2\\,\\text{A}$", "$E_{L,\\text{max}} = \\frac{1}{2}LI_0^2$", "$E_{L,\\text{max}} = \\frac{1}{2} \\times 0{,}5 \\times (0{,}2)^2$", "$E_{L,\\text{max}} = 0{,}5 \\times 0{,}5 \\times 0{,}04 = 0{,}01\\,\\text{J} = 10\\,\\text{mJ}$"], "figure": {"svg": "<svg viewBox=\"0 0 400 100\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"20\" y=\"25\" fill=\"#4A90D9\" font-size=\"13\">I₀ = E/R = 10/50 = 0,2 A</text><text x=\"20\" y=\"50\" fill=\"#64748B\" font-size=\"13\">E_L = ½ × 0,5 × (0,2)² = ½ × 0,5 × 0,04</text><text x=\"20\" y=\"75\" fill=\"#10B981\" font-size=\"14\" font-weight=\"bold\">E_L max = 0,01 J = 10 mJ</text></svg>", "alt_text": "Calcul de l''énergie maximale"}}',
  '{"energie","bobine","regime_permanent","bac_2024"}'
);

