-- Item 859: MCQ — Période propre d'un circuit LC (difficulty 3)
INSERT INTO items (id, skill_id, item_type, difficulty_level, content_language, question, explanation, tags) VALUES
(
  '44444444-0000-0000-0000-000000000859',
  '33333333-0000-0000-0000-000000000030',
  'mcq', 3, 'fr',
  '{"stem": "On considère le circuit LC idéal ci-dessous. L''inductance de la bobine est $L = 40\\,\\text{mH}$ et la capacité du condensateur est $C = 10\\,\\mu\\text{F}$. La période propre $T_0$ des oscillations libres non amorties est :", "latex": true, "figure": {"svg": "<svg viewBox=\"0 0 400 200\" xmlns=\"http://www.w3.org/2000/svg\"><line x1=\"80\" y1=\"30\" x2=\"200\" y2=\"30\" stroke=\"#4A90D9\" stroke-width=\"2\"/><line x1=\"200\" y1=\"30\" x2=\"200\" y2=\"50\" stroke=\"#4A90D9\" stroke-width=\"2\"/><line x1=\"185\" y1=\"50\" x2=\"215\" y2=\"50\" stroke=\"#4A90D9\" stroke-width=\"2.5\"/><line x1=\"190\" y1=\"60\" x2=\"210\" y2=\"60\" stroke=\"#4A90D9\" stroke-width=\"2.5\"/><text x=\"225\" y=\"58\" fill=\"#4A90D9\" font-size=\"13\" font-weight=\"bold\">C</text><line x1=\"200\" y1=\"60\" x2=\"200\" y2=\"170\" stroke=\"#4A90D9\" stroke-width=\"2\"/><line x1=\"200\" y1=\"170\" x2=\"80\" y2=\"170\" stroke=\"#4A90D9\" stroke-width=\"2\"/><line x1=\"80\" y1=\"170\" x2=\"80\" y2=\"130\" stroke=\"#4A90D9\" stroke-width=\"2\"/><path d=\"M75,130 C70,120 90,120 85,110 C80,100 100,100 95,90 C90,80 110,80 105,70\" fill=\"none\" stroke=\"#4A90D9\" stroke-width=\"2\"/><text x=\"55\" y=\"100\" fill=\"#4A90D9\" font-size=\"13\" font-weight=\"bold\">L</text><line x1=\"80\" y1=\"30\" x2=\"80\" y2=\"70\" stroke=\"#4A90D9\" stroke-width=\"2\"/><text x=\"130\" y=\"22\" fill=\"#E8744F\" font-size=\"11\">i →</text><path d=\"M215,100 L215,130\" stroke=\"#E8744F\" stroke-width=\"1.5\"/><path d=\"M212,125 L215,133 L218,125\" fill=\"#E8744F\"/><text x=\"225\" y=\"120\" fill=\"#E8744F\" font-size=\"11\">u_C</text></svg>", "alt_text": "Circuit LC idéal avec bobine L et condensateur C"}, "choices": ["$T_0 \\approx 3{,}97\\,\\text{ms}$", "$T_0 \\approx 1{,}26\\,\\text{ms}$", "$T_0 \\approx 6{,}28\\,\\text{ms}$", "$T_0 \\approx 12{,}57\\,\\text{ms}$"], "correct_index": 0}',
  '{"text_fr": "La période propre d''un circuit LC est $T_0 = 2\\pi\\sqrt{LC}$. On calcule $LC = 40 \\times 10^{-3} \\times 10 \\times 10^{-6} = 4 \\times 10^{-7}$. Donc $\\sqrt{LC} = \\sqrt{4 \\times 10^{-7}} = 2 \\times 10^{-3{,}5} = 6{,}325 \\times 10^{-4}\\,\\text{s}$. Finalement $T_0 = 2\\pi \\times 6{,}325 \\times 10^{-4} \\approx 3{,}97 \\times 10^{-3}\\,\\text{s} = 3{,}97\\,\\text{ms}$.", "steps": ["$T_0 = 2\\pi\\sqrt{LC}$", "$LC = 40 \\times 10^{-3} \\times 10 \\times 10^{-6} = 4 \\times 10^{-7}$", "$\\sqrt{LC} = \\sqrt{4 \\times 10^{-7}} = 6{,}325 \\times 10^{-4}\\,\\text{s}$", "$T_0 = 2\\pi \\times 6{,}325 \\times 10^{-4} \\approx 3{,}97\\,\\text{ms}$"]}',
  '{"periode_propre","circuit_LC","bac_2023"}'
);

-- Item 860: Numeric — Pseudo-période et amortissement (difficulty 4)
INSERT INTO items (id, skill_id, item_type, difficulty_level, content_language, question, explanation, tags) VALUES
(
  '44444444-0000-0000-0000-000000000860',
  '33333333-0000-0000-0000-000000000030',
  'numeric', 4, 'fr',
  '{"stem": "La courbe ci-dessous représente les oscillations amorties de la tension $u_C(t)$ dans un circuit RLC série. On lit graphiquement que 5 pseudo-périodes correspondent à une durée de $40\\,\\text{ms}$. Déterminer la pseudo-période $T$ (en ms) et en déduire la capacité $C$ (en $\\mu\\text{F}$) sachant que $L = 0{,}1\\,\\text{H}$ et que $T \\approx T_0$ (faible amortissement).", "latex": true, "correct_value": 16.2, "tolerance": 0.5, "figure": {"svg": "<svg viewBox=\"0 0 400 250\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"30\" y=\"10\" width=\"360\" height=\"230\" fill=\"#fafafa\" stroke=\"#64748B\" stroke-width=\"1\" rx=\"2\"/><line x1=\"30\" y1=\"125\" x2=\"390\" y2=\"125\" stroke=\"#64748B\" stroke-width=\"1\"/><line x1=\"30\" y1=\"10\" x2=\"30\" y2=\"240\" stroke=\"#64748B\" stroke-width=\"1\"/><text x=\"15\" y=\"130\" fill=\"#64748B\" font-size=\"9\">0</text><text x=\"395\" y=\"128\" fill=\"#64748B\" font-size=\"9\">t</text><text x=\"15\" y=\"15\" fill=\"#64748B\" font-size=\"9\">u_C</text><path d=\"M30,30 C45,30 55,40 65,80 C75,125 80,160 95,195 C105,220 115,220 125,195 C135,160 140,125 150,80 C160,50 170,40 180,60 C190,85 195,125 205,155 C215,175 220,180 230,165 C240,145 245,125 255,100 C265,85 270,82 280,92 C290,105 295,125 305,138 C310,148 315,148 320,142 C325,135 330,125 340,118 C345,112 350,112 355,117 C360,122 365,125 370,127 C380,127 385,126 390,125\" fill=\"none\" stroke=\"#4A90D9\" stroke-width=\"2\"/><path d=\"M30,30 C80,50 140,85 200,105 C260,117 320,123 390,125\" fill=\"none\" stroke=\"#E8744F\" stroke-width=\"1\" stroke-dasharray=\"4,3\"/><path d=\"M30,220 C80,200 140,165 200,145 C260,133 320,127 390,125\" fill=\"none\" stroke=\"#E8744F\" stroke-width=\"1\" stroke-dasharray=\"4,3\"/><line x1=\"30\" y1=\"240\" x2=\"30\" y2=\"245\" stroke=\"#10B981\" stroke-width=\"1\"/><line x1=\"100\" y1=\"240\" x2=\"100\" y2=\"245\" stroke=\"#10B981\" stroke-width=\"1\"/><text x=\"55\" y=\"248\" fill=\"#10B981\" font-size=\"9\" text-anchor=\"middle\">T</text><path d=\"M35,242 L95,242\" stroke=\"#10B981\" stroke-width=\"1\"/><path d=\"M35,239 L35,245\" stroke=\"#10B981\" stroke-width=\"1\"/><path d=\"M95,239 L95,245\" stroke=\"#10B981\" stroke-width=\"1\"/></svg>", "alt_text": "Oscillations amorties u_C(t) dans un circuit RLC série avec enveloppes exponentielles décroissantes"}}',
  '{"text_fr": "La pseudo-période est $T = 40/5 = 8\\,\\text{ms}$. En faible amortissement, $T \\approx T_0 = 2\\pi\\sqrt{LC}$. On en déduit $C = T_0^2 / (4\\pi^2 L)$. Application : $C = (8 \\times 10^{-3})^2 / (4\\pi^2 \\times 0{,}1) = 64 \\times 10^{-6} / (4 \\times 9{,}87 \\times 0{,}1) = 64 \\times 10^{-6} / 3{,}948 = 16{,}2 \\times 10^{-6}\\,\\text{F} = 16{,}2\\,\\mu\\text{F}$.", "steps": ["$T = 40\\,\\text{ms} / 5 = 8\\,\\text{ms}$", "$T \\approx T_0 = 2\\pi\\sqrt{LC}$, donc $T_0^2 = 4\\pi^2 LC$", "$C = T_0^2 / (4\\pi^2 L) = (8 \\times 10^{-3})^2 / (4\\pi^2 \\times 0{,}1)$", "$C = 64 \\times 10^{-6} / 3{,}948 \\approx 16{,}2\\,\\mu\\text{F}$"]}',
  '{"pseudo_periode","amortissement","capacite","bac_2024"}'
);

-- Item 861: True/False — Conservation de l'énergie dans un circuit LC idéal (difficulty 3)
INSERT INTO items (id, skill_id, item_type, difficulty_level, content_language, question, explanation, tags) VALUES
(
  '44444444-0000-0000-0000-000000000861',
  '33333333-0000-0000-0000-000000000030',
  'true_false', 3, 'fr',
  '{"stem": "Dans un circuit LC idéal (sans résistance), les courbes ci-dessous montrent les énergies $E_C$ et $E_L$ en fonction du temps. L''énergie totale $E_T = E_C + E_L$ reste constante au cours du temps.", "latex": true, "correct_answer": true, "figure": {"svg": "<svg viewBox=\"0 0 400 250\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"40\" y=\"10\" width=\"350\" height=\"220\" fill=\"#fafafa\" stroke=\"#64748B\" stroke-width=\"1\" rx=\"2\"/><line x1=\"40\" y1=\"230\" x2=\"390\" y2=\"230\" stroke=\"#64748B\" stroke-width=\"1\"/><line x1=\"40\" y1=\"10\" x2=\"40\" y2=\"230\" stroke=\"#64748B\" stroke-width=\"1\"/><text x=\"25\" y=\"234\" fill=\"#64748B\" font-size=\"9\">0</text><text x=\"395\" y=\"234\" fill=\"#64748B\" font-size=\"9\">t</text><text x=\"10\" y=\"15\" fill=\"#64748B\" font-size=\"9\">E (J)</text><line x1=\"40\" y1=\"40\" x2=\"390\" y2=\"40\" stroke=\"#64748B\" stroke-width=\"1\" stroke-dasharray=\"5,3\"/><text x=\"392\" y=\"44\" fill=\"#64748B\" font-size=\"9\">E_T</text><path d=\"M40,40 C60,60 80,120 100,180 C120,220 140,220 160,180 C180,120 200,60 220,40 C240,60 260,120 280,180 C300,220 320,220 340,180 C360,120 380,60 390,40\" fill=\"none\" stroke=\"#4A90D9\" stroke-width=\"2\"/><text x=\"85\" y=\"215\" fill=\"#4A90D9\" font-size=\"10\">E_C</text><path d=\"M40,230 C60,210 80,150 100,90 C120,50 140,50 160,90 C180,150 200,210 220,230 C240,210 260,150 280,90 C300,50 320,50 340,90 C360,150 380,210 390,230\" fill=\"none\" stroke=\"#E8744F\" stroke-width=\"2\"/><text x=\"85\" y=\"70\" fill=\"#E8744F\" font-size=\"10\">E_L</text></svg>", "alt_text": "Courbes E_C et E_L en opposition de phase, leur somme E_T constante dans un circuit LC idéal"}}',
  '{"text_fr": "Vrai. Dans un circuit LC idéal (résistance nulle), il n''y a aucune dissipation d''énergie par effet Joule. L''énergie totale $E_T = E_C + E_L = \\frac{1}{2}Cu_C^2 + \\frac{1}{2}Li^2$ est conservée. L''énergie oscille entre le condensateur (énergie électrique $E_C$) et la bobine (énergie magnétique $E_L$), mais leur somme reste constante.", "steps": ["Dans un circuit LC idéal, $R = 0$ donc pas de dissipation par effet Joule", "$E_T = E_C + E_L = \\frac{1}{2}Cu_C^2 + \\frac{1}{2}Li^2 = \\text{constante}$", "L''énergie est transférée périodiquement entre C et L", "Sur le graphe : quand $E_C$ est maximale, $E_L$ est nulle et inversement"]}',
  '{"conservation_energie","circuit_LC","transfert","bac_2023"}'
);

-- Item 862: Numeric — Fréquence de résonance (difficulty 4)
INSERT INTO items (id, skill_id, item_type, difficulty_level, content_language, question, explanation, tags) VALUES
(
  '44444444-0000-0000-0000-000000000862',
  '33333333-0000-0000-0000-000000000030',
  'numeric', 4, 'fr',
  '{"stem": "Un circuit RLC série est excité par un générateur de tension sinusoïdale de fréquence variable. La courbe de résonance $I(f)$ ci-dessous montre que l''intensité maximale est obtenue pour $f_0 = 800\\,\\text{Hz}$. Sachant que $L = 50\\,\\text{mH}$, déterminer la capacité $C$ (en nF) du condensateur.", "latex": true, "correct_value": 792, "tolerance": 15, "figure": {"svg": "<svg viewBox=\"0 0 400 250\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"40\" y=\"10\" width=\"350\" height=\"220\" fill=\"#fafafa\" stroke=\"#64748B\" stroke-width=\"1\" rx=\"2\"/><line x1=\"40\" y1=\"230\" x2=\"390\" y2=\"230\" stroke=\"#64748B\" stroke-width=\"1\"/><line x1=\"40\" y1=\"10\" x2=\"40\" y2=\"230\" stroke=\"#64748B\" stroke-width=\"1\"/><text x=\"25\" y=\"234\" fill=\"#64748B\" font-size=\"9\">0</text><text x=\"395\" y=\"234\" fill=\"#64748B\" font-size=\"9\">f (Hz)</text><text x=\"15\" y=\"15\" fill=\"#64748B\" font-size=\"9\">I (A)</text><path d=\"M50,225 C80,222 120,218 160,200 C180,180 195,120 210,40 C225,120 240,180 260,200 C300,218 340,222 380,225\" fill=\"none\" stroke=\"#4A90D9\" stroke-width=\"2.5\"/><line x1=\"210\" y1=\"40\" x2=\"210\" y2=\"230\" stroke=\"#E8744F\" stroke-width=\"1\" stroke-dasharray=\"4,3\"/><text x=\"205\" y=\"245\" fill=\"#E8744F\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"bold\">f₀</text><text x=\"200\" y=\"248\" fill=\"#64748B\" font-size=\"8\">800</text><circle cx=\"210\" cy=\"40\" r=\"4\" fill=\"#E8744F\"/><text x=\"218\" y=\"35\" fill=\"#E8744F\" font-size=\"10\">I_max</text><line x1=\"40\" y1=\"165\" x2=\"390\" y2=\"165\" stroke=\"#10B981\" stroke-width=\"0.5\" stroke-dasharray=\"3,3\"/><text x=\"392\" y=\"168\" fill=\"#10B981\" font-size=\"8\">I_max/√2</text><line x1=\"180\" y1=\"165\" x2=\"180\" y2=\"230\" stroke=\"#10B981\" stroke-width=\"0.5\" stroke-dasharray=\"2,2\"/><line x1=\"242\" y1=\"165\" x2=\"242\" y2=\"230\" stroke=\"#10B981\" stroke-width=\"0.5\" stroke-dasharray=\"2,2\"/><text x=\"175\" y=\"248\" fill=\"#10B981\" font-size=\"8\">f₁</text><text x=\"237\" y=\"248\" fill=\"#10B981\" font-size=\"8\">f₂</text><path d=\"M182,240 L240,240\" stroke=\"#10B981\" stroke-width=\"1\"/><text x=\"211\" y=\"250\" fill=\"#10B981\" font-size=\"8\" text-anchor=\"middle\">Δf</text></svg>", "alt_text": "Courbe de résonance I(f) d''un circuit RLC série, pic à f₀ = 800 Hz, avec bande passante Δf marquée"}}',
  '{"text_fr": "À la résonance, $f_0 = \\frac{1}{2\\pi\\sqrt{LC}}$. On en déduit $C = \\frac{1}{4\\pi^2 f_0^2 L}$. Application : $C = \\frac{1}{4\\pi^2 \\times (800)^2 \\times 50 \\times 10^{-3}} = \\frac{1}{4 \\times 9{,}87 \\times 640000 \\times 0{,}05} = \\frac{1}{1{,}264 \\times 10^6} = 7{,}92 \\times 10^{-7}\\,\\text{F} = 792\\,\\text{nF}$.", "steps": ["$f_0 = \\frac{1}{2\\pi\\sqrt{LC}}$, donc $f_0^2 = \\frac{1}{4\\pi^2 LC}$", "$C = \\frac{1}{4\\pi^2 f_0^2 L}$", "$C = \\frac{1}{4 \\times 9{,}87 \\times (800)^2 \\times 50 \\times 10^{-3}}$", "$C = \\frac{1}{1{,}264 \\times 10^6} \\approx 792\\,\\text{nF}$"]}',
  '{"resonance","frequence_propre","capacite","bac_2024"}'
);

-- Item 863: MCQ — Équation différentielle RLC et régime pseudo-périodique (difficulty 4)
INSERT INTO items (id, skill_id, item_type, difficulty_level, content_language, question, explanation, tags) VALUES
(
  '44444444-0000-0000-0000-000000000863',
  '33333333-0000-0000-0000-000000000030',
  'mcq', 4, 'fr',
  '{"stem": "On considère le circuit RLC série ci-dessous en oscillations libres. Le condensateur est initialement chargé sous la tension $U_0$. On observe les oscillations de $u_C(t)$ sur l''oscilloscope. Quelle est l''expression correcte de l''équation différentielle vérifiée par la charge $q$ du condensateur ?", "latex": true, "figure": {"svg": "<svg viewBox=\"0 0 400 200\" xmlns=\"http://www.w3.org/2000/svg\"><line x1=\"50\" y1=\"30\" x2=\"130\" y2=\"30\" stroke=\"#4A90D9\" stroke-width=\"2\"/><rect x=\"130\" y=\"20\" width=\"50\" height=\"20\" fill=\"none\" stroke=\"#4A90D9\" stroke-width=\"2\" rx=\"2\"/><text x=\"155\" y=\"35\" fill=\"#4A90D9\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"bold\">R</text><line x1=\"180\" y1=\"30\" x2=\"230\" y2=\"30\" stroke=\"#4A90D9\" stroke-width=\"2\"/><path d=\"M230,25 C237,15 243,35 250,25 C257,15 263,35 270,25\" fill=\"none\" stroke=\"#4A90D9\" stroke-width=\"2\"/><text x=\"250\" y=\"48\" fill=\"#4A90D9\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"bold\">L</text><line x1=\"270\" y1=\"30\" x2=\"350\" y2=\"30\" stroke=\"#4A90D9\" stroke-width=\"2\"/><line x1=\"350\" y1=\"30\" x2=\"350\" y2=\"80\" stroke=\"#4A90D9\" stroke-width=\"2\"/><line x1=\"335\" y1=\"80\" x2=\"365\" y2=\"80\" stroke=\"#4A90D9\" stroke-width=\"2.5\"/><line x1=\"340\" y1=\"90\" x2=\"360\" y2=\"90\" stroke=\"#4A90D9\" stroke-width=\"2.5\"/><text x=\"370\" y=\"88\" fill=\"#4A90D9\" font-size=\"12\" font-weight=\"bold\">C</text><line x1=\"350\" y1=\"90\" x2=\"350\" y2=\"170\" stroke=\"#4A90D9\" stroke-width=\"2\"/><line x1=\"350\" y1=\"170\" x2=\"50\" y2=\"170\" stroke=\"#4A90D9\" stroke-width=\"2\"/><line x1=\"50\" y1=\"170\" x2=\"50\" y2=\"30\" stroke=\"#4A90D9\" stroke-width=\"2\"/><text x=\"90\" y=\"22\" fill=\"#E8744F\" font-size=\"10\">i →</text><text x=\"360\" y=\"140\" fill=\"#E8744F\" font-size=\"10\">u_C</text></svg>", "alt_text": "Circuit RLC série avec R, L, C en série, sens du courant i fléché"}, "choices": ["$L\\,\\dfrac{d^2q}{dt^2} + R\\,\\dfrac{dq}{dt} + \\dfrac{q}{C} = 0$", "$L\\,\\dfrac{d^2q}{dt^2} + \\dfrac{q}{C} = 0$", "$L\\,\\dfrac{dq}{dt} + R\\,q + \\dfrac{q}{C} = 0$", "$\\dfrac{d^2q}{dt^2} + \\dfrac{R}{L}\\,\\dfrac{dq}{dt} + \\dfrac{1}{LC}\\,q = E$"], "correct_index": 0}',
  '{"text_fr": "En appliquant la loi des mailles au circuit RLC série en oscillations libres (pas de générateur) : $u_L + u_R + u_C = 0$. Avec $u_L = L\\,di/dt$, $u_R = Ri$, $u_C = q/C$ et $i = dq/dt$, on obtient $L\\,d^2q/dt^2 + R\\,dq/dt + q/C = 0$.", "steps": ["Loi des mailles : $u_L + u_R + u_C = 0$", "$L\\,\\dfrac{di}{dt} + Ri + \\dfrac{q}{C} = 0$", "Or $i = \\dfrac{dq}{dt}$, donc $\\dfrac{di}{dt} = \\dfrac{d^2q}{dt^2}$", "$L\\,\\dfrac{d^2q}{dt^2} + R\\,\\dfrac{dq}{dt} + \\dfrac{q}{C} = 0$"]}',
  '{"equation_differentielle","RLC_serie","oscillations_libres","bac_2023"}'
);

-- Item 864: True/False — Facteur de qualité et sélectivité (difficulty 5)
INSERT INTO items (id, skill_id, item_type, difficulty_level, content_language, question, explanation, tags) VALUES
(
  '44444444-0000-0000-0000-000000000864',
  '33333333-0000-0000-0000-000000000030',
  'true_false', 5, 'fr',
  '{"stem": "En oscillations forcées dans un circuit RLC série, la courbe de résonance ci-dessous montre deux cas : courbe (1) avec $R_1 = 10\\,\\Omega$ et courbe (2) avec $R_2 = 50\\,\\Omega$. Le facteur de qualité $Q$ est plus grand pour le circuit ayant la résistance $R$ la plus grande.", "latex": true, "correct_answer": false, "figure": {"svg": "<svg viewBox=\"0 0 400 250\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"40\" y=\"10\" width=\"350\" height=\"220\" fill=\"#fafafa\" stroke=\"#64748B\" stroke-width=\"1\" rx=\"2\"/><line x1=\"40\" y1=\"230\" x2=\"390\" y2=\"230\" stroke=\"#64748B\" stroke-width=\"1\"/><line x1=\"40\" y1=\"10\" x2=\"40\" y2=\"230\" stroke=\"#64748B\" stroke-width=\"1\"/><text x=\"25\" y=\"234\" fill=\"#64748B\" font-size=\"9\">0</text><text x=\"395\" y=\"234\" fill=\"#64748B\" font-size=\"9\">f</text><text x=\"15\" y=\"15\" fill=\"#64748B\" font-size=\"9\">I</text><path d=\"M60,225 C100,222 150,215 185,170 C200,130 210,40 220,30 C230,40 240,130 255,170 C290,215 340,222 380,225\" fill=\"none\" stroke=\"#4A90D9\" stroke-width=\"2.5\"/><text x=\"300\" y=\"185\" fill=\"#4A90D9\" font-size=\"11\" font-weight=\"bold\">(1) R₁</text><path d=\"M60,222 C100,218 140,200 170,170 C195,140 205,100 220,80 C235,100 245,140 270,170 C300,200 340,218 380,222\" fill=\"none\" stroke=\"#E8744F\" stroke-width=\"2\" stroke-dasharray=\"6,3\"/><text x=\"300\" y=\"205\" fill=\"#E8744F\" font-size=\"11\" font-weight=\"bold\">(2) R₂</text><line x1=\"220\" y1=\"230\" x2=\"220\" y2=\"25\" stroke=\"#64748B\" stroke-width=\"0.5\" stroke-dasharray=\"3,3\"/><text x=\"215\" y=\"245\" fill=\"#64748B\" font-size=\"9\">f₀</text></svg>", "alt_text": "Deux courbes de résonance : (1) pic aigu avec R₁ = 10 Ω et (2) pic aplati avec R₂ = 50 Ω"}}',
  '{"text_fr": "Faux. Le facteur de qualité est $Q = \\frac{1}{R}\\sqrt{\\frac{L}{C}} = \\frac{L\\omega_0}{R}$. Plus $R$ est grande, plus $Q$ est petit, et plus la courbe de résonance est aplatie (sélectivité faible). La courbe (1) avec $R_1 = 10\\,\\Omega$ a un $Q$ plus élevé (pic aigu, grande sélectivité). La courbe (2) avec $R_2 = 50\\,\\Omega$ a un $Q$ plus faible (pic aplati).", "steps": ["$Q = \\frac{1}{R}\\sqrt{\\frac{L}{C}}$ : $Q$ est inversement proportionnel à $R$", "Pour $R_1 = 10\\,\\Omega$ : $Q_1$ est grand → pic aigu (courbe 1)", "Pour $R_2 = 50\\,\\Omega$ : $Q_2$ est petit → pic aplati (courbe 2)", "Conclusion : $Q$ est plus grand pour la résistance la plus petite"]}',
  '{"facteur_qualite","selectivite","resonance","bac_2024"}'
);

-- Item 865: Numeric — Perte d'énergie par cycle dans un RLC amorti (difficulty 5)
INSERT INTO items (id, skill_id, item_type, difficulty_level, content_language, question, explanation, tags) VALUES
(
  '44444444-0000-0000-0000-000000000865',
  '33333333-0000-0000-0000-000000000030',
  'numeric', 5, 'fr',
  '{"stem": "Dans un circuit RLC série ($L = 80\\,\\text{mH}$, $C = 2\\,\\mu\\text{F}$, $R = 20\\,\\Omega$), le condensateur est chargé initialement sous $U_0 = 10\\,\\text{V}$. La courbe ci-dessous montre la décroissance de l''énergie totale. Calculer l''énergie totale initiale $E_0$ (en $\\mu\\text{J}$) du circuit.", "latex": true, "correct_value": 100, "tolerance": 2, "figure": {"svg": "<svg viewBox=\"0 0 400 250\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"40\" y=\"10\" width=\"350\" height=\"220\" fill=\"#fafafa\" stroke=\"#64748B\" stroke-width=\"1\" rx=\"2\"/><line x1=\"40\" y1=\"230\" x2=\"390\" y2=\"230\" stroke=\"#64748B\" stroke-width=\"1\"/><line x1=\"40\" y1=\"10\" x2=\"40\" y2=\"230\" stroke=\"#64748B\" stroke-width=\"1\"/><text x=\"25\" y=\"234\" fill=\"#64748B\" font-size=\"9\">0</text><text x=\"395\" y=\"234\" fill=\"#64748B\" font-size=\"9\">t</text><text x=\"5\" y=\"15\" fill=\"#64748B\" font-size=\"9\">E (μJ)</text><text x=\"25\" y=\"38\" fill=\"#64748B\" font-size=\"9\">100</text><text x=\"30\" y=\"134\" fill=\"#64748B\" font-size=\"9\">50</text><path d=\"M40,30 C80,40 120,60 160,85 C200,115 240,150 280,180 C320,200 360,215 390,220\" fill=\"none\" stroke=\"#E8744F\" stroke-width=\"2.5\"/><text x=\"310\" y=\"185\" fill=\"#E8744F\" font-size=\"11\" font-weight=\"bold\">E_T(t)</text><line x1=\"40\" y1=\"30\" x2=\"55\" y2=\"30\" stroke=\"#10B981\" stroke-width=\"1.5\"/><text x=\"60\" y=\"34\" fill=\"#10B981\" font-size=\"10\">E₀</text><path d=\"M40,30 C60,60 80,100 110,130 C130,110 145,100 160,85 C175,100 190,108 200,115 C215,108 225,103 240,125 C250,120 260,130 280,180\" fill=\"none\" stroke=\"#4A90D9\" stroke-width=\"1.5\" stroke-dasharray=\"4,2\"/><text x=\"145\" y=\"105\" fill=\"#4A90D9\" font-size=\"9\">oscillations</text></svg>", "alt_text": "Décroissance exponentielle de l''énergie totale E_T dans un circuit RLC amorti, de E₀ = 100 μJ vers 0"}}',
  '{"text_fr": "À l''instant initial, toute l''énergie est stockée dans le condensateur : $E_0 = E_C(0) = \\frac{1}{2}CU_0^2$. Application : $E_0 = \\frac{1}{2} \\times 2 \\times 10^{-6} \\times (10)^2 = \\frac{1}{2} \\times 2 \\times 10^{-6} \\times 100 = 10^{-4}\\,\\text{J} = 100\\,\\mu\\text{J}$.", "steps": ["À $t = 0$, le courant est nul ($i = 0$) donc $E_L = 0$", "$E_0 = E_C(0) = \\frac{1}{2}CU_0^2$", "$E_0 = \\frac{1}{2} \\times 2 \\times 10^{-6} \\times (10)^2$", "$E_0 = 100 \\times 10^{-6}\\,\\text{J} = 100\\,\\mu\\text{J}$"]}',
  '{"energie_initiale","amortissement","dissipation","bac_2024"}'
);

-- Item 866: MCQ — Portrait de phase i(q) d'un circuit LC (difficulty 5)
INSERT INTO items (id, skill_id, item_type, difficulty_level, content_language, question, explanation, tags) VALUES
(
  '44444444-0000-0000-0000-000000000866',
  '33333333-0000-0000-0000-000000000030',
  'mcq', 5, 'fr',
  '{"stem": "On trace le portrait de phase $i = f(q)$ d''un circuit LC idéal ($L = 0{,}5\\,\\text{H}$, $C = 0{,}2\\,\\mu\\text{F}$, $Q_0 = 50\\,\\mu\\text{C}$). La figure ci-dessous représente cette courbe. Quelle est sa forme géométrique et quelle est la valeur maximale de l''intensité $I_0$ (en mA) ?", "latex": true, "figure": {"svg": "<svg viewBox=\"0 0 400 280\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"10\" width=\"370\" height=\"260\" fill=\"#fafafa\" stroke=\"#64748B\" stroke-width=\"1\" rx=\"2\"/><line x1=\"200\" y1=\"270\" x2=\"200\" y2=\"10\" stroke=\"#64748B\" stroke-width=\"1\"/><line x1=\"20\" y1=\"140\" x2=\"390\" y2=\"140\" stroke=\"#64748B\" stroke-width=\"1\"/><text x=\"385\" y=\"155\" fill=\"#64748B\" font-size=\"10\">q</text><text x=\"205\" y=\"20\" fill=\"#64748B\" font-size=\"10\">i</text><text x=\"195\" y=\"155\" fill=\"#64748B\" font-size=\"9\">0</text><ellipse cx=\"200\" cy=\"140\" rx=\"130\" ry=\"100\" fill=\"none\" stroke=\"#4A90D9\" stroke-width=\"2.5\"/><path d=\"M200,40 L210,50\" stroke=\"#E8744F\" stroke-width=\"2\"/><path d=\"M205,42 L210,50 L215,44\" fill=\"none\" stroke=\"#E8744F\" stroke-width=\"1.5\"/><text x=\"335\" y=\"135\" fill=\"#E8744F\" font-size=\"10\" font-weight=\"bold\">Q₀</text><text x=\"55\" y=\"135\" fill=\"#E8744F\" font-size=\"10\" font-weight=\"bold\">-Q₀</text><text x=\"205\" y=\"38\" fill=\"#E8744F\" font-size=\"10\" font-weight=\"bold\">I₀</text><text x=\"205\" y=\"255\" fill=\"#E8744F\" font-size=\"10\" font-weight=\"bold\">-I₀</text><line x1=\"330\" y1=\"140\" x2=\"330\" y2=\"145\" stroke=\"#64748B\" stroke-width=\"1\"/><line x1=\"70\" y1=\"140\" x2=\"70\" y2=\"145\" stroke=\"#64748B\" stroke-width=\"1\"/><line x1=\"200\" y1=\"40\" x2=\"195\" y2=\"40\" stroke=\"#64748B\" stroke-width=\"1\"/><line x1=\"200\" y1=\"240\" x2=\"195\" y2=\"240\" stroke=\"#64748B\" stroke-width=\"1\"/></svg>", "alt_text": "Portrait de phase i = f(q) d''un circuit LC ideal : ellipse centree sur l''origine, sens horaire"}, "choices": ["Ellipse, $I_0 \\approx 15{,}8\\,\\text{mA}$", "Cercle, $I_0 = 50\\,\\text{mA}$", "Ellipse, $I_0 = 50\\,\\text{mA}$", "Cercle, $I_0 \\approx 15{,}8\\,\\text{mA}$"], "correct_index": 0}',
  '{"text_fr": "Le portrait de phase $i = f(q)$ d''un circuit LC ideal est une ellipse. Par conservation de l''energie : $\\frac{1}{2}Li^2 + \\frac{q^2}{2C} = \\frac{Q_0^2}{2C}$, soit $\\frac{i^2}{I_0^2} + \\frac{q^2}{Q_0^2} = 1$ avec $I_0 = Q_0 \\cdot \\omega_0 = Q_0 / \\sqrt{LC}$. Calcul : $LC = 0{,}5 \\times 0{,}2 \\times 10^{-6} = 10^{-7}$. $\\sqrt{LC} = \\sqrt{10^{-7}} = 3{,}162 \\times 10^{-4}$. $\\omega_0 = 1/\\sqrt{LC} = 3162\\,\\text{rad/s}$. $I_0 = 50 \\times 10^{-6} \\times 3162 = 0{,}1581 \\times 10^{-1} = 15{,}8 \\times 10^{-3}\\,\\text{A} = 15{,}8\\,\\text{mA}$. C''est bien une ellipse (et non un cercle) car les demi-axes $Q_0$ et $I_0$ ont des dimensions differentes.", "steps": ["Conservation de l''energie : $\\frac{1}{2}Li^2 + \\frac{q^2}{2C} = \\frac{Q_0^2}{2C}$", "Forme canonique : $\\frac{i^2}{I_0^2} + \\frac{q^2}{Q_0^2} = 1$ → c''est une ellipse", "$I_0 = Q_0 \\cdot \\omega_0 = Q_0 / \\sqrt{LC}$", "$LC = 0{,}5 \\times 0{,}2 \\times 10^{-6} = 10^{-7}$, $\\sqrt{LC} = 3{,}162 \\times 10^{-4}\\,\\text{s}$", "$I_0 = 50 \\times 10^{-6} / (3{,}162 \\times 10^{-4}) \\approx 15{,}8\\,\\text{mA}$"]}',
  '{"portrait_de_phase","circuit_LC","ellipse","bac_2024"}'
);
